from odoo import api, SUPERUSER_ID


def migrate(cr, version):
    env = api.Environment(cr, SUPERUSER_ID, {})
    manager = env.ref('petty_cash_management.group_petty_cash_manager')
    # Remove stale manager-step tasks generated by the previous legacy fallback.
    # Keep explicit group assignments and completed review history unchanged.
    reports = env['petty.cash'].search([('state', '=', 'manager_approval')])
    for report in reports:
        activities = report.activity_ids.filtered(
            lambda a: a.summary == '%s: Manager Approval required' % report.name
            and a.user_id not in manager.users
        )
        activities.unlink()
